/**
 * Thread-scoped worktree directory. All sibling agents in the same thread
 * (e.g. illie + illie-codex) bind-mount this same host path at
 * `/workspace/worktrees` inside their containers so they collaborate on
 * the same checkout.
 *
 * Key derivation: `<thread-id>` (preferred) or `dm-<platform-id>` fallback.
 * Slack thread ids encode `slack:<channel>:<ts>` and Discord encodes
 * `discord:<guild>:<channel>:<thread>` — both globally unique, including
 * the platform prefix. So just using the thread_id alone is enough.
 *
 * For DM / non-threaded channels (thread_id=null), `dm-<platform_id>` keeps
 * the dir stable per conversation. Critically, when TWO sibling agents are
 * wired to the same channel via TWO Slack apps (`slack-illysium` +
 * `slack-illiecodex` both seeing `slack:C0AJA89MN2E`), they share the same
 * platform_id and therefore the same worktree path — that's what makes
 * cross-bot collaboration work.
 *
 * Nested dirs (not a flat `<mg>:<thread>` key) because Docker's `-v` flag
 * uses `:` as the field separator between source:target:options. A colon in
 * the host path turns `-v src:dst` into a three-part `src:dst:opts` which
 * Docker rejects with exit 125. fsSlug strips any embedded colons too.
 */
export function threadWorktreeDir(platformId: string, threadId: string | null): string {
  const tid = threadId ?? `dm-${platformId}`;
  return path.join(threadsBaseDir(), fsSlug(tid), 'worktrees');
}

/** Per-session Graphify cache. Sessions never share this directory. */
export function sessionGraphifyCacheDir(agentGroupId: string, sessionId: string): string {
  return path.join(sessionDir(agentGroupId, sessionId), 'graphify-cache');
}

/** Thread-scoped Graphify cache shared by sibling agents in one conversation. */
export function threadGraphifyCacheDir(platformId: string, threadId: string | null): string {
  const tid = threadId ?? `dm-${platformId}`;
  return path.join(threadsBaseDir(), fsSlug(tid), 'graphify-cache');
}

/** Install-scoped runtime state for the Graphify gateway. */
export function graphifyRuntimeDir(): string {
  return path.join(DATA_DIR, 'graphify-runtime');
}

/** Path to the host-owned inbound DB (messages_in + delivered). */
export function inboundDbPath(agentGroupId: string, sessionId: string): string {
  return path.join(sessionDir(agentGroupId, sessionId), 'inbound.db');
}

/** Path to the container-owned outbound DB (messages_out + processing_ack). */
export function outboundDbPath(agentGroupId: string, sessionId: string): string {
  return path.join(sessionDir(agentGroupId, sessionId), 'outbound.db');
}

/** Path to the container heartbeat file (touched instead of DB writes). */

const mounts: VolumeMount[] = [];
const sessDir = sessionDir(agentGroup.id, session.id);
const groupDir = path.resolve(GROUPS_DIR, agentGroup.folder);

// Session folder at /workspace (contains inbound.db, outbound.db, outbox/, .claude/).
//
// The session dir parent is mounted RW because the container legitimately
// writes: outbound.db (its own), outbox/<id>/ (file deliveries), and
// .heartbeat (liveness touch).
//
// inbound.db, however, is host-owned and MUST be unwritable from the
// container. Without this, a compromised agent could forge admin
// approvals by directly INSERT-ing into the `delivered` table, trivially
// bypassing the email-gate, send_file ack, and any future host→container
// signaling that rides on inbound.db. The file-level RO overlay below
// reuses the same host file; Docker applies mount rules in order, so the
// `:ro` on inbound.db overrides the parent mount's RW permission for
// that specific path.
//
// The SDK-level `readonly: true` open in container/agent-runner/src/db/
// connection.ts is belt and suspenders. The mount is the real boundary.
mounts.push({ hostPath: sessDir, containerPath: '/workspace', readonly: false });
const inboundDbFile = path.join(sessDir, 'inbound.db');
if (fs.existsSync(inboundDbFile)) {
  mounts.push({ hostPath: inboundDbFile, containerPath: '/workspace/inbound.db', readonly: true });
}

// Graphify indexes persist beside the checkout scope they describe. Normal
// sessions keep an isolated cache; thread-worktree siblings share the cache
// derived from the same platform/thread key. Runtime coordination remains
// install-scoped and is never placed under a source checkout or host home.
let graphifyCache = sessionGraphifyCacheDir(agentGroup.id, session.id);
if (session.messaging_group_id && process.env.NANOCLAW_THREAD_WORKTREES === '1') {
  const mg = getMessagingGroup(session.messaging_group_id);
  if (mg) graphifyCache = threadGraphifyCacheDir(mg.platform_id, session.thread_id);
}
const graphifyRuntime = graphifyRuntimeDir();
fs.mkdirSync(graphifyCache, { recursive: true });
fs.mkdirSync(graphifyRuntime, { recursive: true });
mounts.push({ hostPath: graphifyCache, containerPath: '/workspace/.cache/graphify', readonly: false });
mounts.push({ hostPath: graphifyRuntime, containerPath: '/run/nanoclaw-graphify', readonly: false });

// Thread-scoped worktrees: shared bind-mount across all sibling agents
// (Claude + Codex) in the same thread, so collaborative code edits land
// in one repo checkout regardless of which agent ran them. The session
// dir mount above provides `/workspace/worktrees` by default; this layered
// mount overrides it with the thread-keyed path. Docker applies mounts
// in declaration order — inner overrides outer for the subpath.
//
// The thread key collapses to `<mg>:msg-<first-msg-id>` when threadId is
// null (DM channels) so every conversation still gets a deterministic
// worktree identity rather than sharing one global `<mg>:none` dir.
//
// Gated on NANOCLAW_THREAD_WORKTREES=1 for backward-compat: existing
// single-agent deployments keep their session-scoped worktrees and don't
// lose access on container restart after this deploy. Set the env var to
// opt in (required for sibling-agent collaboration to share code state).
if (session.messaging_group_id && process.env.NANOCLAW_THREAD_WORKTREES === '1') {
  // Two-bot sibling design: illie (slack-illysium) and illie-codex
  // (slack-illiecodex) each have their own MG row in this channel,
  // but they share the same platform_id (the Slack channel id) and the
  // same thread_id from chat-sdk-bridge. Keying threadWorktreeDir on
  // platform_id + thread_id resolves both bots to the same worktree dir,
  // so collaborative code edits in a thread are visible across siblings.
  const mg = getMessagingGroup(session.messaging_group_id);
  if (mg) {
    const tDir = threadWorktreeDir(mg.platform_id, session.thread_id);
    fs.mkdirSync(tDir, { recursive: true });
    mounts.push({ hostPath: tDir, containerPath: '/workspace/worktrees', readonly: false });
  }
}

// Agent group folder at /workspace/agent (RW for working files + CLAUDE.local.md)
mounts.push({ hostPath: groupDir, containerPath: '/workspace/agent', readonly: false });

